  NumAlias n = 3.14;
  DoubleAlias d = 3.1415;
  BoolAlias b = true;
  StringAlias s = "Lily was here";

  Expect.equals(1, i);
  Expect.equals(3.14, n);
  Expect.equals(3.1415, d);
  Expect.isTrue(b);
  Expect.equals("Lily was here", s);

  i = 3;
  n = 1;
  d = 4;
  b = false;
  s = "Run, Forrest, Run!";

  Expect.equals(3, i);
  Expect.equals(1, n);
  Expect.equals(4, d);
  Expect.isFalse(b);
  Expect.equals("Run, Forrest, Run!", s);
}

